var defaultEdge = { rounded: "0", curved: "0", dashed: "0", endArrow: "classic", startArrow: "none" };
function nearestColor(color, palette) {
  const rgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
  const [r, g, b] = rgb(color);
  let best;
  let bestD = Infinity;
  for (const p2 of palette) {
    if (!/^#[0-9a-f]{6}$/.test(p2)) continue;
    const [pr, pg, pb] = rgb(p2);
    const d = (r - pr) ** 2 + (g - pg) ** 2 + (b - pb) ** 2;
    if (d < bestD) {
      bestD = d;
      best = p2;
    }
  }
  return best;
}

